<?php require_once 'config/functions.php';require_login();$uid=user_id();$action=$_GET['action']??'list';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)($_POST['id']??0);$title=trim($_POST['title']??'');$date=$_POST['entry_date']??date('Y-m-d');$content=trim($_POST['content']??'');$mood=$_POST['mood']??null;if(isset($_POST['delete'])){$pdo->prepare('DELETE FROM journals WHERE id=? AND user_id=?')->execute([$id,$uid]);flash('Entry deleted.');redirect('journal.php');}if($title&&$content){if($id){$pdo->prepare('UPDATE journals SET title=?,entry_date=?,content=?,mood=? WHERE id=? AND user_id=?')->execute([$title,$date,$content,$mood,$id,$uid]);flash('Journal updated.');}else{$pdo->prepare('INSERT INTO journals(user_id,title,entry_date,content,mood) VALUES(?,?,?,?,?)')->execute([$uid,$title,$date,$content,$mood]);flash('Journal saved.');}redirect('journal.php');}}
if($action==='edit'){$q=$pdo->prepare('SELECT * FROM journals WHERE id=? AND user_id=?');$q->execute([(int)($_GET['id']??0),$uid]);$entry=$q->fetch();if(!$entry)redirect('journal.php');}if($action==='new')$entry=['id'=>0,'title'=>'','entry_date'=>date('Y-m-d'),'content'=>'','mood'=>''];page_header('My Journal');?><div class="card"><div class="row" style="justify-content:space-between"><h3>Your memories and thoughts</h3><a class="btn" href="journal.php?action=new">＋ New Entry</a></div><?php if(in_array($action,['new','edit'])):?><form method="post" class="form"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="id" value="<?=h($entry['id'])?>"><div class="grid grid-2"><div class="field"><label>Title</label><input name="title" value="<?=h($entry['title'])?>" placeholder="A little moment today..." required></div><div class="field"><label>Date</label><input type="date" name="entry_date" value="<?=h($entry['entry_date'])?>" required></div></div><div class="field"><label>Mood (optional)</label><select name="mood"><option value="">Select mood</option><?php foreach(['Happy','Calm','Loved','Excited','Okay','Sad','Anxious','Angry','Tired'] as $m):?><option <?=$entry['mood']===$m?'selected':''?>><?=h($m)?></option><?php endforeach;?></select></div><div class="field"><label>Your journal</label><textarea name="content" placeholder="Write freely. This space is yours..." required><?=h($entry['content'])?></textarea></div><div class="row"><button>Save Entry</button><a class="btn secondary" href="journal.php">Back</a><?php if($entry['id']):?><button class="btn danger" name="delete" value="1" data-confirm="Delete this entry permanently?">Delete</button><?php endif;?></div></form><?php else:?><form class="row" method="get"><input type="hidden" name="action" value="list"><input name="search" placeholder="Search entries..." value="<?=h($_GET['search']??'')?>"><button>Search</button><a class="btn secondary" href="journal.php">Clear</a></form><?php $search='%'.($_GET['search']??'').'%';$q=$pdo->prepare('SELECT * FROM journals WHERE user_id=? AND (title LIKE ? OR content LIKE ?) ORDER BY entry_date DESC,id DESC');$q->execute([$uid,$search,$search]);$list=$q->fetchAll();if(!$list):?><div class="empty">No entries yet. Write your first journal entry 🌷</div><?php else:foreach($list as $r):?><div class="entry"><div class="row" style="justify-content:space-between"><h3><?=h($r['title'])?></h3><a class="btn secondary" href="journal.php?action=edit&id=<?=$r['id']?>">Edit</a></div><div class="small"><?=h($r['entry_date'])?> · <?=h($r['mood']??'')?></div><p><?=nl2br(h($r['content']))?></p></div><?php endforeach;endif;endif;?></div><?php page_footer();
